param([switch]$ExecutionAuthorized)
# Input preparation only. Copy authored XML/retained binaries to one fresh seed, never run a program.
$ErrorActionPreference='Stop';$tests=Split-Path -Parent $PSScriptRoot;$logs=Join-Path $tests 'logs';$seed=Join-Path $tests 'outputs\upl_column_public_seed_r1';$record=Join-Path $logs 'upl_column_public_r1.inputs.json'
function E([string]$p){$f=Get-Item -LiteralPath $p;[ordered]@{path=$f.FullName;bytes=[long]$f.Length;sha256=(Get-FileHash -LiteralPath $p -Algorithm SHA256).Hash.ToLowerInvariant()}}
function J([string]$p){[IO.File]::ReadAllText($p)|ConvertFrom-Json}
function Need([bool]$ok,[string]$why){if(!$ok){throw $why}}
function V($rows){foreach($e in $rows){Need (![string]::IsNullOrEmpty($e.path)) 'Missing Entry';$a=E $e.path;Need ($a.bytes -eq $e.bytes -and $a.sha256 -ieq $e.sha256) ('Changed retained/authored artifact: '+$e.path)}}
function Fresh($paths){foreach($p in $paths){Need (!(Test-Path -LiteralPath $p)) ('Retained path protected: '+$p)}}
function PhysicalDom([string]$p,[bool]$reverseMaster){$d=New-Object Xml.XmlDocument;$d.PreserveWhitespace=$false;$d.Load($p);$nodes=$d.SelectNodes('/case/execution/special/hydromechanics/HydroMechDynamicSeepage');Need ($nodes.Count -eq 1 -and $nodes[0].GetAttribute('value') -ceq $(if($reverseMaster){'1'}else{'0'})) 'Exactly one expected public master required';if($reverseMaster){$nodes[0].SetAttribute('value','0')};foreach($a in @($d.SelectNodes('//@comment'))){[void]$a.OwnerElement.RemoveAttributeNode($a)};foreach($n in @($d.SelectNodes('//comment()'))){[void]$n.ParentNode.RemoveChild($n)};return $d.OuterXml}
Need $ExecutionAuthorized 'Root full-read and explicit Prepare authorization required';Fresh @($seed,$record)
$smokePath=Join-Path $logs 'upl_case02_smoke_r1.inputs.json';$windowPath=Join-Path $logs 'upl_case02_flux_window25_r1.inputs.json';$smokeEntry=E $smokePath;$windowEntry=E $windowPath
Need ($smokeEntry.sha256 -ceq '215aa1b4e94e82f0eaf663685aea525a093cbe5c8cb70f1b3b866e5ebc357d70' -and $windowEntry.sha256 -ceq '8281306010ac1bf01393dc97abed0f272dea30d7567754fb1d5934f03886be05') 'Exact sealed private input manifests required'
$smoke=J $smokePath;$window=J $windowPath;Need ($smoke.prepared -and $window.prepared -and !$smoke.physical_acceptance -and !$window.physical_acceptance) 'Retained prepared inputs required'
$declarations=@(@{window='smoke';old=$smoke;manifest=$smokeEntry;sha='91361a48145bc12104484081172631dd3dde7667369a829ec733366139ab3336';dt=2.5e-6;end=5e-6;steps=2;samples=3},@{window='coarse';old=@($window.jobs|Where-Object{$_.window -ceq 'coarse'})[0];manifest=$windowEntry;sha='c6108504dba705347308dfb3615c945d702efb2e137399237286558d62957bc1';dt=2.5e-6;end=0.025;steps=10000;samples=769},@{window='half';old=@($window.jobs|Where-Object{$_.window -ceq 'half'})[0];manifest=$windowEntry;sha='e1871b60a83484775e37f89f3ce614a9629358c8e887b0c8dfce8ff779c54ad8';dt=1.25e-6;end=0.025;steps=20000;samples=769})
$bindings=@((E $PSCommandPath),(E (Join-Path $tests 'notes\upl_column_public_prepare_r1.json')),$smokeEntry,$windowEntry);$plans=@()
foreach($d in $declarations){$o=$d.old;$configuration=E (Join-Path $tests ('configs\upl_column_public_'+$d.window+'_r1.xml'))
  Need ($null -ne $o -and $o.runtime.sha256 -ceq $d.sha -and $o.initial_BI4.sha256 -ceq 'f2836ffeb049fc777de7687608dd5dfbece81f78440bdc01f21890ee3e3fedac' -and $o.normals.sha256 -ceq '0509139e4fee0c57d3b480f213c4b9062cf467ce6a24c0a1d13d87148a885f97' -and $o.dt_s -eq $d.dt -and $o.end_s -eq $d.end -and $o.steps -eq $d.steps) 'Retained same-window input identity/count differs'
  V @($o.configuration,$o.runtime,$o.initial_BI4,$o.normals,$configuration);Need ((PhysicalDom $o.runtime.path $false) -ceq (PhysicalDom $configuration.path $true)) 'Only master0-to1 plus comments/indentation may differ'
  $bindings+=@($configuration,$o.configuration,$o.runtime,$o.initial_BI4,$o.normals);$plans+=@{declaration=$d;configuration=$configuration}
}
V $bindings;[void](New-Item -ItemType Directory -Path $seed);$jobs=@();$files=@();$failure=$null;$unchanged=$false
try{foreach($p in $plans){$d=$p.declaration;$o=$d.old;$prefix=Join-Path $seed ('upl_column_public_'+$d.window+'_r1');$runtime=$prefix+'.xml';$bi4=$prefix+'.bi4';$normal=$prefix+'_Normals.nbi4';Fresh @($runtime,$bi4,$normal)
  Copy-Item -LiteralPath $p.configuration.path -Destination $runtime;Copy-Item -LiteralPath $o.initial_BI4.path -Destination $bi4;Copy-Item -LiteralPath $o.normals.path -Destination $normal;$re=E $runtime;$be=E $bi4;$ne=E $normal
  Need ($re.bytes -eq $p.configuration.bytes -and $re.sha256 -ceq $p.configuration.sha256 -and $be.bytes -eq $o.initial_BI4.bytes -and $be.sha256 -ceq $o.initial_BI4.sha256 -and $ne.bytes -eq $o.normals.bytes -and $ne.sha256 -ceq $o.normals.sha256) 'Exact authored-runtime/retained-binary copy differs'
  $jobs+=@{window=$d.window;backend_shared_runtime=$true;configuration=$p.configuration;runtime=$re;input_prefix=$prefix;initial_BI4=$be;normals=$ne;dt_s=$d.dt;end_s=$d.end;steps=$d.steps;expected_samples=$d.samples;required_CLI=@('-mdbc_freeslip','-svres',('-nsteps:'+$d.steps));retained_required_CLI=$o.required_CLI;retained_manifest=$d.manifest;retained_configuration=$o.configuration;retained_runtime=$o.runtime;retained_initial_BI4=$o.initial_BI4;retained_normals=$o.normals;physical_XML_equal_except_master=$true;master_value=1;conductivity_model=0;conductivity_Ck=0;initial_particle_fields_rewritten=$false};$files+=@($re,$be,$ne)
}}catch{$failure=$_.Exception.Message}
try{V $bindings;V $files;$unchanged=$true}catch{if(!$failure){$failure=$_.Exception.Message}}
$passed=(!$failure -and $unchanged -and $jobs.Count -eq 3 -and $files.Count -eq 9);$value=[ordered]@{stage='upl_column_public_prepare_r1';passed=[bool]$passed;prepared=[bool]$passed;scope='Input preparation only, not numerical admission';author=(E $PSCommandPath);note=(E (Join-Path $tests 'notes\upl_column_public_prepare_r1.json'));retained_manifests=@($smokeEntry,$windowEntry);seed_directory=$seed;jobs=$jobs;inputs=$bindings;bindings=$bindings;files=$files;physical_XML_equal_except_master=[bool]$passed;input_sources_unchanged=$unchanged;native_counts_declared_from_retained_XML=@{total=1040;soil=1000;fixed=40};GenCase_invoked=$false;solver_reader_or_build_invoked=$false;formal_files_changed=$false;physical_acceptance=$false;failure=$failure}
Fresh @($record);[IO.File]::WriteAllText($record,($value|ConvertTo-Json -Depth 16)+[Environment]::NewLine,(New-Object Text.UTF8Encoding($false)));if(!$passed){throw "Prepare failed; preserve fresh partials and $record, never overwrite retained evidence"};Write-Output "Three public candidate inputs prepared, no program run: $record"
